import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.UpdateAdventureSettings{NoPvM: true, NoMvP: false, ImmutableWorld: true, ShowNameTags: false, AutoJump: true}
MIXED = bytes.fromhex("0100010001")

# generated by gophertunnel b8bd735:
# &packet.UpdateAdventureSettings{}
ALL_CLEAR = bytes.fromhex("0000000000")

GOLDENS = [
    pytest.param(
        v2225.UpdateAdventureSettingsPacket(
            adventure_settings=v2225.AdventureSettings(
                no_pv_m=True,
                no_mv_p=False,
                immutable_world=True,
                show_name_tags=False,
                auto_jump=True,
            )
        ),
        MIXED,
        id="mixed",
    ),
    pytest.param(v2225.UpdateAdventureSettingsPacket(), ALL_CLEAR, id="five-separate-bytes-not-a-bitfield"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_adventure_settings_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_adventure_settings_decodes_from_its_golden(packet, golden):
    assert v2225.UpdateAdventureSettingsPacket.from_bytes(golden) == packet
